<?php require_once 'config/db.php';require_once 'includes/auth.php';require_role(['customer']);if(!isset($_SESSION['cart']))$_SESSION['cart']=[];if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['product_id'])){$id=(int)$_POST['product_id'];$q=max(1,(int)($_POST['quantity']??1));$s=$conn->prepare('SELECT stock FROM products WHERE id=?');$s->bind_param('i',$id);$s->execute();$p=$s->get_result()->fetch_assoc();if($p&&$q<=$p['stock'])$_SESSION['cart'][$id]=min($p['stock'],($_SESSION['cart'][$id]??0)+$q);header('Location:cart.php?msg=Cart+updated');exit;}if(isset($_GET['remove'])){unset($_SESSION['cart'][(int)$_GET['remove']]);header('Location:cart.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['update'])){foreach($_POST['qty']??[] as $id=>$q){$id=(int)$id;$q=(int)$q;if($q<1)unset($_SESSION['cart'][$id]);else $_SESSION['cart'][$id]=$q;}header('Location:cart.php?msg=Cart+updated');exit;}$items=[];$total=0;foreach($_SESSION['cart'] as $id=>$q){$s=$conn->prepare('SELECT * FROM products WHERE id=?');$s->bind_param('i',$id);$s->execute();if($p=$s->get_result()->fetch_assoc()){$p['qty']=$q;$items[]=$p;$total+=$p['price']*$q;}}include 'includes/header.php';?><div class="card"><h2>Your Cart</h2><?php if(!$items):?><p>Your cart is empty. <a href="products.php">Browse products</a>.</p><?php else:?><form method="post"><input type="hidden" name="update" value="1"><table><tr><th>Product</th><th>Price</th><th>Quantity</th><th>Line total</th><th></th></tr><?php foreach($items as $p):?><tr><td><?=h($p['name'])?></td><td>₹<?=number_format($p['price'],2)?></td><td><input type="number" name="qty[<?=$p['id']?>]" min="0" max="<?=$p['stock']?>" value="<?=$p['qty']?>" style="width:80px"></td><td>₹<?=number_format($p['price']*$p['qty'],2)?></td><td><a href="?remove=<?=$p['id']?>">Remove</a></td></tr><?php endforeach;?></table><p><b>Subtotal (tax calculated at checkout): ₹<?=number_format($total,2)?></b></p><button class="btn">Update Cart</button> <a class="btn success" href="checkout.php">Proceed to confirmation</a></form><?php endif;?></div><?php include 'includes/footer.php';?>